// crucible-adapter.test — exercised against REAL replay fixtures (fixtures/crucible/*.json),
// generated by actually playing runs through the vendored crucible engine (scripts/play-crucible.mjs
// + scripts/generate-fixtures.mjs): one certified-minimal playthrough and two deliberately
// imperfect-but-legal ones. The one rejected-* exception is hand-built and labeled, exercising the
// rejection path a real move log could never hit on purpose.

import { test } from "node:test";
import assert from "node:assert/strict";
import { verify, project, id, name } from "../adapters/crucible.mjs";
import { replay } from "../adapters/vendor/crucible/replay.mts";
import { loadFixture } from "./helpers.mjs";

test("adapter identity", () => {
  assert.equal(id, "crucible");
  assert.equal(name, "Crucible Daily");
});

test("verify() on the certified-minimal real run agrees with the vendored replay()", async () => {
  const bundle = await loadFixture("crucible", "2026-08-19-certified.json");
  const v = verify(bundle);
  assert.equal(v.valid, true);
  assert.equal(v.settled, true);

  const direct = replay(v.seed, bundle.moveLog);
  assert.equal(direct.totalCost, v.totalCost);
  assert.equal(direct.settled, v.settled);
});

test("verify() on a naive, over-budget real run still settles and reports the overage honestly", async () => {
  const bundle = await loadFixture("crucible", "2026-08-19-naive.json");
  const v = verify(bundle);
  assert.equal(v.valid, true);
  assert.equal(v.settled, true);
  assert.ok(v.totalCost >= 0);
  assert.ok(v.startBudget > 0);
});

test("verify() rejects a real illegal move (unknown bond id)", async () => {
  const bundle = await loadFixture("crucible", "rejected-illegal-move.json");
  const v = verify(bundle);
  assert.equal(v.valid, false);
  assert.equal(v.rejected, "illegal-move");
});

test("verify() requires exactly one of replayBundle.date / replayBundle.seed", () => {
  assert.throws(() => verify({ moveLog: [] }), TypeError);
  assert.throws(() => verify({ date: "2026-08-19", seed: "x", moveLog: [] }), TypeError);
});

test("project() on a valid verification returns TUFTE-shaped tiles including the real per-move cost table", async () => {
  const bundle = await loadFixture("crucible", "2026-08-19-naive.json");
  const v = verify(bundle);
  const p = project(bundle, v);
  assert.ok(p.tiles.some((t) => t.role === "now"));
  const moveTile = p.tiles.find((t) => t.id === "moves");
  assert.ok(moveTile);
  assert.match(moveTile.html, /MERGE|SPLIT/);
  const ids = p.tiles.map((t) => t.id).filter(Boolean);
  assert.equal(new Set(ids).size, ids.length);
});

test("project() on a rejected verification still returns a renderable, honest page", async () => {
  const bundle = await loadFixture("crucible", "rejected-illegal-move.json");
  const v = verify(bundle);
  const p = project(bundle, v);
  assert.ok(Array.isArray(p.tiles) && p.tiles.length > 0);
  assert.match(p.subtitle ?? "", /rejected/i);
});

test("two different real seeds (2026-08-19 vs 2026-07-04) produce different tangles", async () => {
  const a = verify(await loadFixture("crucible", "2026-08-19-naive.json"));
  const b = verify(await loadFixture("crucible", "2026-07-04-naive.json"));
  assert.notEqual(a.seed, b.seed);
  assert.notDeepEqual(a.finalTangle, b.finalTangle);
});

test("determinism: verifying the same real bundle twice yields identical output", async () => {
  const bundle = await loadFixture("crucible", "2026-08-19-certified.json");
  const a = verify(bundle);
  const b = verify(bundle);
  assert.deepEqual(a, b);
});
